import json
import os
from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class Settings:
    trusted_issuer: str
    certificate_path: Path
    bind_host: str
    port: int

    @classmethod
    def from_env(cls) -> "Settings":
        config_path = Path(
            os.environ.get("IDENTITY_GATEWAY_CONFIG", "config/idp.json")
        ).resolve()
        data = json.loads(config_path.read_text())
        certificate = Path(data["certificate_path"])
        if not certificate.is_absolute():
            certificate = config_path.parent / certificate
        return cls(
            trusted_issuer=os.environ.get(
                "IDENTITY_GATEWAY_ISSUER", data["trusted_issuer"]
            ),
            certificate_path=certificate,
            bind_host=os.environ.get("IDENTITY_GATEWAY_BIND", data["bind_host"]),
            port=int(os.environ.get("IDENTITY_GATEWAY_PORT", data["port"])),
        )
from __future__ import annotations

from threading import RLock


class SessionStore:
    def __init__(self):
        self._lock = RLock()
        self._active_sessions: set[str] = set()
        self._pending_logout: dict[str, str] = {}

    def add(self, session_id: str) -> None:
        with self._lock:
            self._active_sessions.add(session_id)

    def register_logout(self, request_id: str, session_id: str) -> None:
        with self._lock:
            if session_id not in self._active_sessions:
                raise KeyError(session_id)
            self._pending_logout[request_id] = session_id

    def complete_logout(self, request_id: str) -> bool:
        with self._lock:
            session_id = self._pending_logout.pop(request_id, None)
            if session_id is None:
                return False
            self._active_sessions.discard(session_id)
            return True

    def is_active(self, session_id: str) -> bool:
        with self._lock:
            return session_id in self._active_sessions
